    }
  }
  override fun writeValue(stream: ByteArrayOutputStream, value: Any?)   {
    when (value) {
      is PlatformSourceType -> {
        stream.write(129)
        writeValue(stream, value.raw.toLong())
      }
      is PlatformVideoFormat -> {
        stream.write(130)
        writeValue(stream, value.raw.toLong())
      }
      is PlatformPlaybackState -> {
        stream.write(131)
        writeValue(stream, value.raw.toLong())
      }
      is PlatformSource -> {
        stream.write(132)
        writeValue(stream, value.toList())
      }
      is PlatformPlayerOptions -> {
        stream.write(133)
        writeValue(stream, value.toList())
      }
      is PlatformPlayerCreation -> {
        stream.write(134)
        writeValue(stream, value.toList())
      }
      is PlatformCapabilities -> {
        stream.write(135)
        writeValue(stream, value.toList())
      }
      is PlatformPosition -> {
        stream.write(136)
        writeValue(stream, value.toList())
      }
      is PlatformInitializedEvent -> {
        stream.write(137)
        writeValue(stream, value.toList())
      }
      is PlatformStateEvent -> {
        stream.write(138)
        writeValue(stream, value.toList())
      }
      is PlatformIsPlayingEvent -> {
        stream.write(139)
        writeValue(stream, value.toList())
      }
      is PlatformVideoSizeEvent -> {
        stream.write(140)
